/* eslint-disable solid/reactivity */

import { createMemo, type ParentComponent } from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";

import { Activatable, ActivatableProps } from "./activatable";

interface ArrowButtonComponentProps extends ActivatableProps {
	/** Set to true if the arrow should point right and false to point left. Default: false */
	right?: boolean;
	/** Set to true to hide this component when a controller is active. Default: false */
	hideForController?: boolean;
}

const ArrowButtonComponent: ParentComponent<ArrowButtonComponentProps> = (props) => {
	props.audio ??= {};
	props.audio.group ??= "audio-pager";

	const isHidden = createMemo(() => props.hideForController && IsControllerActive());

	return (
		<Activatable
			{...props}
			class={`relative ${props.class ?? ""}`}
			classList={{
				"img-arrow-highlight": !props.right,
				"img-arrow-highlight-flipped": props.right,
				hidden: isHidden(),
			}}
			name="ArrowButton"
		>
			<div
				class="absolute inset-0 transition-opacity"
				classList={{
					"opacity-0": !props.disabled,
					"opacity-1": props.disabled,
					"img-arrow-disabled": !props.right,
					"img-arrow-disabled-flipped": props.right,
				}}
			/>
		</Activatable>
	);
};

/**
 * An Arrow Button component.
 * A button styled like an arrow.
 * ```tsx
 * // Example - Right Arrow
 * <ArrowButton onActivate={() => console.log("activated")} right={true} />
 * ```
 * Default implementation: {@link ArrowButtonComponent} Based on: {@link Activatable}
 * @param {ArrowButtonComponentProps} props See {@link ArrowButtonComponentProps} for a full list of properties
 *
 * Commonly Used Properties:
 * @param {boolean} props.right Set to true if the arrow should point right and false to point left. Default: false
 * @param {boolean} props.disabled Is this control disabled both visually and for input? Default: false
 * @param {string} props.hotkeyAction The name of a hotkey action which activates this component. Default: undefined
 * @param {string} props.name The name of the component set as the data-name property - useful for debugging or searching the DOM tree. Default: "Activatable"
 * @param {() => void} props.onActivate Event which triggers when the control is activated either through hotkey, mouse click, touch, or other user interaction. Default: undefined
 */
export const ArrowButton = ComponentRegistry.register({
	name: "ArrowButton",
	createInstance: ArrowButtonComponent,
	images: ["blp:base_component-arrow", "blp:base_component-arrow_dis"],
});
